set -e
cd "$(dirname "$0")"
openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"
surl --directory site --cert server.pem --key server.key https://127.0.0.1:8080/ &
sleep 1
curl --cacert server.pem https://127.0.0.1:8080/hello.txt
kill $(jobs -p)
